mapper.select:
select read_id, notice_id, user_id, read_time
from sys_notice_read
where user_id = #{userId} and notice_id = #{noticeId}

select count(1)
from sys_notice a
left join sys_notice_read b on a.notice_id = b.notice_id and b.user_id = #{userId}
where a.status = '0'
and b.read_id is null
and a.notice_id in (
    select notice_id from sys_notice_scope where (
        scope_type = '3' and target_id = #{userId}
        or scope_type = '1' and target_id = (select dept_id from sys_user where user_id = #{userId})
        or scope_type = '2' and target_id in (
            select post_id from sys_user_post where user_id = #{userId}
            union
            select role_id from sys_user_role where user_id = #{userId}
        )
    )
)

select read_id, notice_id, user_id, read_time
from sys_notice_read
where user_id = #{userId}
